-- Capture only writes made inside an active management operation; request health updates stay outside this journal.

CREATE TRIGGER management_capture_donation_service_health_insert AFTER INSERT ON donation_service_health
WHEN EXISTS(SELECT 1 FROM management_capture_context) AND 1
BEGIN
 INSERT INTO management_capture_totals(event_id,kind,created) SELECT event_id,'donation_service_health',1 FROM management_capture_context WHERE id=1
 ON CONFLICT(event_id,kind) DO UPDATE SET created=created+1;
 UPDATE management_capture_totals SET omitted=omitted+1 WHERE event_id=(SELECT event_id FROM management_capture_context) AND kind='donation_service_health'
 AND (SELECT COUNT(*) FROM management_capture_rows WHERE event_id=management_capture_totals.event_id)>=256
 AND NOT EXISTS(SELECT 1 FROM management_capture_rows WHERE event_id=management_capture_totals.event_id AND kind='donation_service_health' AND target_id=CAST(NEW.id AS TEXT));
